// ── Cross-device sync (sync.js is the transport; this is the state) ──
// Sync across devices is the same problem as sync across tabs: union the
// transcripts, take the freshest scalar of each chat, and honour tombstones.
// So the network path reuses exactly the merge above rather than inventing a
// second one. sync.js encrypts what collectSync() returns, ships the
// ciphertext through the gateway's opaque mailbox, and feeds what comes back
// to applySync().

/// Union an incoming tombstone map into a stored one, keeping the later time
/// for any id in both and pruning anything past its TTL.
export function mergeTombMap(key, incoming) {
	if (incoming && typeof incoming === 'object') {
		var m = tombMemMap(key);
		Object.keys(incoming).forEach(function (id) {
			var ts = incoming[id];
			if (typeof ts === 'number' && (!m[id] || ts > m[id])) m[id] = ts;
		});
	}
	var out = tombMapNow(key);
	tombCacheWrite(key);
	// Durable in IndexedDB, so a peer's deletion is recorded on the receiver and
	// not merely applied in memory (S-SYNC #6). Fire-and-forget for callers that
	// do not gate on it (the device roster); `applyChats`/`applyDiamonds` AWAIT
	// the same write before they delete or import.
	ChatStore.putTombs(key, out);
	return out;
}

/// A stored tombstone map, with anything past its TTL pruned. The generic form
/// of loadTombs/loadMsgTombs/loadDiamondTombs above, written once so a module
/// that keeps its own map — models.js, mail.js — does not have to keep its own
/// TTL with it.
export function loadTombMap(key) {
	return tombMapNow(key);
}

/// Record that something was deleted on purpose, so the other device deletes
/// it too rather than handing it back on the next pull. Resolves whether the
/// durable write landed. `at` is the deletion's stamp where the caller holds one
/// past the record it removes (models.js); now, otherwise.
export function tombstoneIn(key, id, at) {
	if (!key || !id) return Promise.resolve(false);
	return persistTombs(key, [id], at || Date.now());
}

// ── The devices that sync this account ────────────────────
// Pairing moves the identity WHOLE, so a second device ends up holding the
// SAME keypair: the gateway cannot tell the two apart, and a redeemed pairing
// leaves no record on the server to read back. So there is no list to fetch.
// What can still be told is built the way everything else in this file is —
// each device writes its own line, the parcel carries the lines, the merge
// unions them — and it answers exactly one question: is this account on more
// than one device? Not which paired with which, and not a way to sign one
// out: under one shared keypair nothing could enforce a revocation, and a
// button that pretended otherwise would be worse than no button.
//
// A line carries TWO names. What the device says about itself ("Chromium on
// Linux") is all it can know unaided, and two of a user's machines say it
// identically; what its owner calls it ("Kitchen laptop") is the useful one,
// and only the user can supply it. The chosen one is kept separately, with a
// stamp of its own, so a rename typed on ANY device reaches the rest — see
// mergeDevices for why it cannot ride on `seen`.
// The id THIS FILE minted for itself before the two id spaces were joined on
// 2026-09-12. Read only by `migrateLegacySelfLine`, which moves what the old
// line carried onto the identity-id line and then removes this key.
var DEVICE_ID_KEY_LEGACY = 'daimond-device-id';
var DEVICES_KEY    = 'daimond-devices';		// the merged roster: id -> { name, label, created, namedAt, seen }
// Devices taken off the list on purpose. The roster is a UNION merge, so a
// line dropped here is simply handed back by the next parcel that carries it;
// a tombstone is how the removal survives that, exactly as it does for chats
// and Diamonds. What it is NOT is a revocation — see `removeDevice`.
export var DEVICE_TOMBS_KEY = 'daimond-device-tombs';
// This browser refused `navigator.storage.persist()`. A browser fact, per
// device: a refusal answers every later ask the same way, so the Workspace ·
// Browser row stops offering it (r569, #astat-store was a dead tap).
export var STORE_REFUSED_KEY = 'daimond-store-refused';

/// Can asking the browser to keep the workspace change anything here?
export function storeAskable(sto, kept) {
	var refused = false;
	try { refused = localStorage.getItem(STORE_REFUSED_KEY) === '1'; } catch (e) { /* no store */ }
	return !!(sto && typeof sto.persist === 'function') && !kept && !refused;
}
// old id -> { to, at }: an EXPLICIT record that one roster line superseded
// another. Written by `migrateLegacySelfLine` and by nothing else, and the only
// thing that can call a line "replaced" (`rosterLiveness`) -- a guess from two
// lines sharing a name is what tombstoned live peers. LOCAL: the migration
// already tombstones the old line and re-keys the nomination, and both of those
// ride the parcel, so nothing here needs a wire section of its own.
var DEVICE_SUPER_KEY = 'daimond-device-super';
// A name typed into the pairing dialog on a device that has no roster line
// yet. pairing.js writes it; the first collect here takes it and clears it.
var DEVICE_PAIR_LABEL_KEY = 'daimond-pair-label';
// How stale this device's own `seen` may get before a collect refreshes it.
// NOT every collect: sync skips a push whose parcel stringifies to what it
// last sent, and a stamp that moved every time would defeat that skip and put
// the whole parcel back on the wire for nothing. Five minutes is finer than
// anything the roster shows, so the reading loses nothing by it.
var SEEN_REFRESH_MS   = 5 * 60 * 1000;
var DEVICE_ROSTER_MAX = 24;			// keeps the parcel, and the list, bounded.
var DEVICE_NAME_MAX   = 64;			// a name, not a paragraph. Both names share it.
// 32 hex is what identity.js mints and therefore what every id minted from now
// on is. 16 is the LEGACY width this file used to mint, accepted so a stored
// roster, a stored nomination and a peer still carrying old lines all decode
// while the migration works through them.
//
// AND A RUNNER'S. A paired runner (Kimberlite) holds an id the GATEWAY minted
// (gateway/src/handlers/runner_pair.rs: `util::gen_token(DEVICE_ID_LEN)`): sixteen
// characters of util.rs's TOKEN_CHARSET, lower-case letters less j, l and o, and
// digits. Not hex, so until STARFIX (UNBLOCK-36) this pattern refused it and the
// owner's star on the argonaut runner's row did nothing at all: `nominateDevice`
// returned null, and the roster, the merge and the name memory dropped its lines
// the same way. Sixteen hex is a subset of that alphabet, so the legacy width is
// still admitted. ONE contract for every id the account can hold; cloud.js
// `PEER_RE` and markshere.js `REF_DEVICES_RE` carry the same one, and
// www/js/runnerstar.test.mjs pins all three to the gateway's own minting.
export var DEVICE_ID_RE      = /^(?:[0-9a-f]{32}|[0-9a-ikmnp-z]{16})$/;
// The LEGACY width on its own. Nothing has minted one of these since the id
// spaces were joined, so a line still keyed this way is a record a device wrote
// BEFORE it reloaded -- which is why the Devices panel does not draw one as a
// device (`renderDevices`).
export var LEGACY_ID_RE      = /^[0-9a-f]{16}$/;

/// This machine's name, once the Hand has said hello and named it (see
/// `applyHandHostname`). Empty until then, and for the whole of a session with
/// no Hand -- a browser cannot read a hostname on its own.
var _handHostname = '';

/// A millisecond stamp, or 0 when there is none to be had.
///
/// NOT `n | 0`: an epoch-ms value is far past 32 bits, and the truncation is
/// inconsistently wrong — a fresher stamp can come out smaller than an older
/// one, so the freshest side loses. (models.js keeps its own copy of this for
/// the same reason; each file here is its own closure.)
export function ms(v) {
	return (typeof v === 'number' && isFinite(v) && v > 0) ? Math.floor(v) : 0;
}

/// Held only when neither identity.js nor storage can supply an id. Without it,
/// every call would mint another and the roster would fill with devices that
/// existed for one function call.
var _deviceIdFallback = null;

/// THE device id -- the very same one presence beats under, the lease records as
/// `holder`, and an errand carries as `dispatchedBy` (identity.js `deviceId`).
/// There is ONE device-id space and this is it.
///
/// There were TWO until 2026-09-12. identity.js minted 32 hex for presence and
/// the lease; this file minted its own 16 hex for the roster; nothing ever
/// compared equal across them. So `rosterLiveness` found no roster id in presence
/// and called EVERY line stale, a live same-name presence entry under the other id
/// made the owner's OWN row read "replaced", and the prune button that offered to
/// clear it called `removeDevice` on this device's id, which refuses. The roster
/// wanted exactly what identity.js already had: an id that is per DEVICE (it never
/// travels in the bundle or the parcel, so two paired devices differ) and per
/// ACCOUNT (it is kept beside the account's keys, so two accounts at one browser
/// are never linkable by it).
///
/// Thirty-two hex characters can never be an array index, so a map keyed by these
/// keeps its insertion order through JSON.stringify -- which is what the sorted,
/// stable serialisation below rests on.
export function deviceId() {
	var id = '';
	try { id = String((window.DaimondIdentity && DaimondIdentity.deviceId()) || ''); }
	catch (e) { id = ''; }
	if (DEVICE_ID_RE.test(id)) return id;
	// identity.js absent or refused. A freshly minted id would key the roster under
	// something presence never beats, which is the fault above, so the legacy key is
	// preferred over minting while it is still there.
	if (_deviceIdFallback) return _deviceIdFallback;
	try { id = String(localStorage.getItem(DEVICE_ID_KEY_LEGACY) || ''); } catch (e) { id = ''; }
	if (DEVICE_ID_RE.test(id)) { _deviceIdFallback = id; return id; }
	var b = new Uint8Array(16);
	crypto.getRandomValues(b);
	_deviceIdFallback = Array.prototype.map.call(b, function (x) { return (x + 256).toString(16).slice(1); }).join('');
	return _deviceIdFallback;
}

/// The browser a user-agent string names, for anything that does not offer
/// `navigator.userAgentData`. Order matters: every one of these also says
/// "Safari" or "Chrome" somewhere, so the specific tokens are tested first.
function uaBrand(ua) {
	if (/\b(Firefox|FxiOS)\//.test(ua)) return 'Firefox';
	if (/\bEdg(A|iOS)?\//.test(ua))    return 'Edge';
	if (/\bOPR\//.test(ua))            return 'Opera';
	if (/\bSamsungBrowser\//.test(ua)) return 'Samsung Internet';
	if (/\b(Chrome|CriOS)\//.test(ua)) return 'Chrome';
	if (/\bSafari\//.test(ua))         return 'Safari';
	return '';
}

/// The short word for a browser brand, however it named itself.
///
/// `navigator.userAgentData.brands` hands back "Google Chrome" and "Microsoft
/// Edge" verbatim, which is where "Google Chrome on Linux" came from -- the
/// vendor's own name, not the one a person would say out loud. Tested first
/// against the same tokens `uaBrand` uses on the user-agent string, so the two
/// paths agree; a name neither recognises just loses a vendor prefix.
function shortBrand(name) {
	var n = String(name || '');
	if (/\bFirefox\b/i.test(n))        return 'Firefox';
	if (/\bEdge\b/i.test(n))           return 'Edge';
	if (/\bOpera\b/i.test(n))          return 'Opera';
	if (/\bSamsung\b/i.test(n))        return 'Samsung Internet';
	if (/\bChrome\b/i.test(n))         return 'Chrome';
	if (/\bSafari\b/i.test(n))         return 'Safari';
	return n.replace(/^Google\s+/i, '').replace(/^Microsoft\s+/i, '');
}

/// The browser the lens `boot` event names (LENS-UA, 26 Oct 2026): its engine
/// (Blink, Gecko or WebKit), its brand in `shortBrand`'s words and its major
/// version, so "which browsers does he use" is answered from data. Nothing
/// finer rides: no minor version, no OS build. `uad` is
/// `navigator.userAgentData`, preferred where present because Chromium's
/// reduced user-agent string is frozen in every field but the major.
export function browserOf(ua, uad) {
	ua = String(ua || '');
	var brand = '', major = null;
	try {
		var b = (uad && uad.brands) || [];
		for (var i = 0; i < b.length; i++) {
			var n = b[i] && b[i].brand;
			if (!n || /not.*brand/i.test(n)) continue;	// the deliberate nonsense entry
			// A named browser beats the engine it is built on.
			if (!brand || /^chromium$/i.test(brand)) { brand = String(n); major = parseInt(b[i].version, 10); }
		}
	} catch (e) { brand = ''; major = null; }
	if (!brand) brand = uaBrand(ua);
	brand = shortBrand(brand);
	// Every iOS browser is WebKit underneath, whatever it calls itself.
	var ios = /\b(iPhone|iPad|iPod)\b/.test(ua);
	var engine = ios                                        ? 'WebKit'
		: /\bFirefox\//.test(ua)                           ? 'Gecko'
		: /\b(Chrome|Chromium|Edg|OPR|SamsungBrowser)\//.test(ua) || /chromium/i.test(brandsOf(uad)) ? 'Blink'
		: /\bAppleWebKit\//.test(ua)                       ? 'WebKit'
		: '';
	// A Home Screen app names no browser and no `Version/`: it is Safari's engine,
	// and on iOS that engine's major is the OS's.
	if (!brand && ios) brand = 'Safari';
	if (!(major > 0)) {
		var tok = { Firefox: '(?:Firefox|FxiOS)', Edge: 'Edg(?:A|iOS)?', Opera: 'OPR',
			'Samsung Internet': 'SamsungBrowser', Chrome: '(?:Chrome|CriOS)', Safari: 'Version' }[brand];
		var m = tok ? new RegExp('\\b' + tok + '\\/(\\d+)').exec(ua) : null;
		if (!m && brand === 'Safari' && ios) m = /\bOS (\d+)_/.exec(ua);
		major = m ? parseInt(m[1], 10) : null;
	}
	return { engine: engine, brand: brand, major: major > 0 ? major : null };
}

/// The brand names `userAgentData` lists, joined, or '' when it cannot say.
function brandsOf(uad) {
	try { return ((uad && uad.brands) || []).map(function (x) { return (x && x.brand) || ''; }).join(' '); }
	catch (e) { return ''; }
}

/// The platform a user-agent string names. Coarse on purpose: "Windows", not
/// a version — the roster answers "which of my devices", not "what is
/// installed on it".
function uaPlatform(ua) {
	if (/\bAndroid\b/.test(ua))            return 'Android';
	if (/\b(iPhone|iPad|iPod)\b/.test(ua)) return 'iOS';
	if (/\bCrOS\b/.test(ua))               return 'ChromeOS';
	if (/\bMac OS X\b/.test(ua))           return 'macOS';
	if (/\bWindows\b/.test(ua))            return 'Windows';
	if (/\bLinux\b/.test(ua))              return 'Linux';
	return '';
}

/// How this device describes itself, worked out once when it first joins the
/// roster. Only what the browser volunteers about itself is used — brands and
/// platform, nothing measured, nothing that would narrow this browser down to
/// this browser — UNLESS the machine hand has named this computer, which is a
/// name the user already knows and not a fingerprint. An environment that says
/// nothing recognisable is simply "This device", which is still an honest
/// answer to "how many".
export function deviceName() {
	var brand = '', plat = '';
	try {
		var d = navigator.userAgentData;
		if (d) {
			plat = String(d.platform || '');
			var b = d.brands || [];
			for (var i = 0; i < b.length; i++) {
				var n = b[i] && b[i].brand;
				if (!n || /not.*brand/i.test(n)) continue;	// the deliberate nonsense entry
				// A named browser beats the engine it is built on.
				if (!brand || /^chromium$/i.test(brand)) brand = String(n);
			}
		}
	} catch (e) { /* fall through to the user-agent string */ }
	var ua = '';
	try { ua = String(navigator.userAgent || ''); } catch (e) { ua = ''; }
	if (!brand) brand = uaBrand(ua);
	brand = shortBrand(brand);
	if (!plat)  plat  = uaPlatform(ua);
	if (_handHostname) return t('devices.on_host', { brand: brand || t('devices.unknown'), host: _handHostname });
	if (brand && plat) return t('devices.on_platform', { brand: brand, platform: plat });
	return brand || plat || t('devices.unknown');
}

/// How THIS device describes itself when its line is first minted: what it says
/// about itself, with four hex of its own id on the end -- "Chrome on Linux ·
/// 7e2a" -- or, once the machine hand has named this computer, "Chrome on
/// argonaut" with no tail at all, because two machines do not share a hostname
/// the way two Linux Chromes share a platform string.
///
/// Without a hostname, `deviceName()` reads the browser and the platform and
/// nothing else, by design, so two of a user's Linux Chromes derive the same
/// words. A fleet where two rows read identically cannot be told apart by eye,
/// and routing that matched a device by its label seated whichever twin beat
/// fresher. The suffix is the id's own tail, which is already printed beside
/// every row, so the two are distinct from the moment they mint -- and a name
/// its owner has typed is never touched by this.
export function deviceSelfName(id) {
	var base = deviceName();
	if (_handHostname) return base.slice(0, DEVICE_NAME_MAX);
	var tail = String(id || '').slice(-4);
	if (!tail) return base;
	return String(base + ' · ' + tail).slice(0, DEVICE_NAME_MAX);
}

/// The machine hand has just said hello and named this computer: fold that
/// into this device's own roster line, but ONLY while nobody has typed a name
/// for it -- a label the user gave always wins and this never overwrites one.
///
/// Idempotent: a hand that reconnects with the same hostname, or a call before
/// this device has a roster line at all (`touchSelfDevice` mints one, and
/// `deviceSelfName` reads `_handHostname` itself), changes nothing. `seen` is
/// bumped when the name does change, the same way a build change bumps it, so
/// the freshest-wins merge carries the new name to the rest of the fleet.
export function applyHandHostname(host) {
	host = String(host || '').trim();
	if (!host || host === _handHostname) return;
	_handHostname = host;
	var id = deviceId(), reg = loadDevices(), me = reg[id];
	if (!me || me.label) return;
	var name = deviceSelfName(id);
	if (name === me.name) return;
	me.name = name;
	me.seen = Date.now();
	saveDevices(reg);
}

// ── A hand older than the deletion meter, told once per (host, version) ──

/// The machine hand's hello named a build older than the deletion meter, so
/// the engine has made every folder read-only to a command and to a file
/// tool (`command_fence` in src/tools.rs) until it updates.
///
/// A PENDING NOTICE, not the modal this used to raise (until 2026-09-24). The
/// hello lands whenever the hand connects, which is as often mid-turn as not,
/// and a modal there put its own backdrop under the person's very next click
/// -- closing it unread and losing the click with it (traced in
/// `dev/verify_handrun.mjs`'s regression; see `~/usr/code/ai/claude/specs/
/// daimond_handrun_fix_20260924.md`, "Left open"). A tile in the Pending
/// panel covers nothing and blocks nothing, and waits on no answer.
///
/// TOLD ONCE PER (host, version), by the notice's key: not raised while a tile for
/// it is up in this tab or another, and not again once it has been taken down. A
/// hand that updates, or reconnects under a different host, is different news.
export function noteHandStale(host, version) {
	var key = 'hand-stale|' + String(host || '') + '|' + String(version || '');
	if (Pending.noticed(key) || Pending.noticeUp(key)) return;
	Pending.add({
		kind:     'notice',
		key:      key,
		headline: t('hand.stale_title'),
		detail:   t('hand.stale_body', { host: host || t('hand.stale_here') }),
	});
}

/// One roster line, cleaned: two names that fit, and stamps that are stamps.
///
/// A FIXED field order, for the same reason saveDevices sorts the ids: the
/// same line has to serialise to the same bytes every time, or sync stops
/// skipping the push it should skip.
///
/// A line written before names existed has neither field, and decodes to an
/// empty label stamped 0. Zero is the right absence here — unlike the `touched`
/// stamp elsewhere, where it meant "never touched" and lost real edits —
/// because no name at all SHOULD lose to any name anybody has actually given.
function deviceEntry(d) {
	var e = {
		name:    String((d && d.name) || '').slice(0, DEVICE_NAME_MAX),
		label:   String((d && d.label) || '').slice(0, DEVICE_NAME_MAX),
		created: ms(d && d.created),
		namedAt: ms(d && d.namedAt),
		seen:    ms(d && d.seen),
		// The build this device was last running. It rides WITH the line on
		// `seen` (touchSelfDevice bumps `seen` when the build changes), so a
		// device that updates carries its new build to the fleet on the next
		// sync -- which is what lets the Devices panel show every device's build
		// and flag one left on a superseded build. A line from before this
		// existed carries '' (unknown), which never reads as stale. Last in the
		// FIXED field order, so an unchanged roster still serialises byte-for-byte
		// for a device whose build is empty and the push still skips.
		build:   String((d && d.build) || '').slice(0, 64),
	};
	// Is this MACHINE a phone or tablet? Its own answer, from real signals
	// (mobile.js `isMobileDevice`), so the hand-off election seats a device rather
	// than a NAME: a phone called "gilgamesh" is still a phone. OMITTED, not
	// stamped false, when the device never said -- a line written before this
	// existed must read as "cannot say" (the name inference then stands in), never
	// as "desktop", and an omitted key keeps such a line byte-identical so the
	// push still skips.
	if (typeof (d && d.mobile) === 'boolean') e.mobile = d.mobile;
	// This MACHINE runs a handed-off turn on the set its asker sent (D-20261018-09 OR).
	// Only ever true, and only from the device itself (`touchSelfDevice`): a line
	// without it is a build before the Models menu, which runs a following chat on its
	// own default, so no turn is handed to it (`honoursModelSet`).
	if (d && d.modelset === true) e.modelset = true;
	return e;
}

/// What a device is called on screen: the user's name for it when they have
/// given one, otherwise what the device says about itself.
export function deviceShownName(d) {
	return (d && d.label) || (d && d.name) || t('devices.unknown');
}

/// The name typed into the pairing dialog on this device, taken and cleared.
///
/// Redeeming a pairing code happens BEFORE this device has a roster line: the
/// line is minted on the first collect, which is after the reload the dialog
/// performs. So pairing.js parks the name here and the mint consumes it —
/// once, so it names this device and no other.
function pendingDeviceLabel() {
	var v = null;
	try { v = localStorage.getItem(DEVICE_PAIR_LABEL_KEY); } catch (e) { return ''; }
	if (v == null) return '';
	try { localStorage.removeItem(DEVICE_PAIR_LABEL_KEY); } catch (e) { /* best effort */ }
	return String(v).trim().slice(0, DEVICE_NAME_MAX);
}

/// Whether a line has been removed and has not been heard from since.
///
/// The comparison is against `seen`, not a flat "is it tombstoned". A device
/// that is still in use refreshes its own stamp, and a line stamped AFTER the
/// removal is that device saying it is still here — which the list has to
/// show, because pretending otherwise is the dishonesty this whole section is
/// written to avoid.
function deviceRemoved(tombs, id, seen) {
	return !!tombs[id] && ms(seen) <= tombs[id];
}

/// The supersession records, as `old id -> new id`. Anything malformed is dropped,
/// so a hand-edited or half-written store cannot mark a live device replaced.
export function loadSupers() {
	var raw = readJson(DEVICE_SUPER_KEY, {}), out = {};
	if (!raw || typeof raw !== 'object') return out;
	Object.keys(raw).forEach(function (id) {
		var to = raw[id] && raw[id].to;
		if (!DEVICE_ID_RE.test(id) || !DEVICE_ID_RE.test(String(to || ''))) return;
		out[id] = String(to);
	});
	return out;
}

/// Record that `to` has taken `old`'s place. Written once, by the migration.
function recordSuper(old, to) {
	if (!DEVICE_ID_RE.test(String(old || '')) || !DEVICE_ID_RE.test(String(to || ''))) return;
	var raw = readJson(DEVICE_SUPER_KEY, {});
	if (!raw || typeof raw !== 'object') raw = {};
	raw[old] = { to: String(to), at: Date.now() };
	try { localStorage.setItem(DEVICE_SUPER_KEY, JSON.stringify(raw)); } catch (e) { /* best effort */ }
}

/// The stored roster, with anything that is not a device dropped, and
/// anything removed on purpose left out.
export function loadDevices() {
	var raw = DaimondStore.get(DEVICES_KEY, {}), out = {};
	if (!raw || typeof raw !== 'object') return out;
	var tombs = loadTombMap(DEVICE_TOMBS_KEY);
	Object.keys(raw).forEach(function (id) {
		if (!DEVICE_ID_RE.test(id) || !raw[id] || typeof raw[id] !== 'object') return;
		if (deviceRemoved(tombs, id, raw[id].seen)) return;
		out[id] = deviceEntry(raw[id]);
	});
	return out;
}

/// Take a device off the list.
///
/// It removes a LINE, and nothing more. Pairing hands the second device the
/// same keypair, so there is nothing here that could sign one out; what this
/// answers is the smaller and real complaint that the list fills with machines
/// the user no longer has. A device still in use writes itself back on its
/// next sync, and that is the honest outcome rather than a bug.
export function removeDevice(id) {
	if (!id || id === deviceId()) return null;	// this device would only re-mint itself
	tombstoneIn(DEVICE_TOMBS_KEY, id);
	// A nomination on a device being taken off the list is meaningless -- the star
	// would point at a line that is no longer here -- so clear it. The empty record
	// propagates the clearing on its own fresher `at`, like handle and look.
	if (id === nominatedDeviceId()) nominateDevice('');
	var reg = loadDevices();
	delete reg[id];
	return saveDevices(reg);
}

/// Write the roster back, and return what was written.
///
/// SORTED by id, and each line built in a fixed field order, so the same set
/// of devices is always the same bytes. Anything whose serialisation followed
/// enumeration order would look like a change on every collect and push for
/// ever — the same trap the provider export above is written to avoid.
function saveDevices(reg) {
	var out = rosterRecord(reg);
	DaimondStore.put(DEVICES_KEY, out, mergeRosters);
	return out;
}

/// The roster as it is stored: bounded, sorted by id, each line in its fixed
/// field order.
function rosterRecord(reg) {
	var ids = Object.keys(reg);
	if (ids.length > DEVICE_ROSTER_MAX) {
		// Bounded, dropping the least recently seen — but never this device,
		// which is the one line the user is certain to be looking for.
		var self = deviceId();
		var keep = ids.slice().sort(function (a, b) { return ms(reg[b].seen) - ms(reg[a].seen); })
			.slice(0, DEVICE_ROSTER_MAX);
		if (reg[self] && keep.indexOf(self) === -1) keep[keep.length - 1] = self;
		ids = keep;
	}
	var out = {};
	ids.sort().forEach(function (id) { out[id] = deviceEntry(reg[id]); });
	return out;
}

/// Move what this device's LEGACY roster line carried onto its identity-id line,
/// once, and retire the legacy line. Answers whether anything was moved.
///
/// Before the two id spaces were joined this device wrote its roster line under an
/// id of this file's own minting. That line holds the only copy of what the user
/// typed for this machine, when it was created, and which build it was on, so
/// switching id without it would lose the name and show the machine as brand new.
/// The old line is then TOMBSTONED, not merely deleted: the roster is an add-only
/// union, so a peer still holding the old line would hand it straight back, and the
/// tombstone rides the parcel so every device drops it too. A peer cannot re-mint
/// it either -- its own `deviceId()` is its own identity id, and this is the only
/// place the legacy key is read at all.
///
/// The NOMINATION is re-keyed where it named the old id, or the account's star
/// would be left pointing at a line that has just been tombstoned -- which is the
/// stranded-nominee fault the whole reconcile exists to answer, reintroduced by
/// the fix for it.
function migrateLegacySelfLine(reg, id, now) {
	var old = '';
	try { old = String(localStorage.getItem(DEVICE_ID_KEY_LEGACY) || ''); } catch (e) { return false; }
	if (!old || old === id || !/^[0-9a-f]{16}$/.test(old)) {
		if (old) { try { localStorage.removeItem(DEVICE_ID_KEY_LEGACY); } catch (e) { /* best effort */ } }
		return false;
	}
	var line = reg[old];
	if (line) {
		var me = reg[id];
		if (!me) me = reg[id] = { name: String(line.name || '') || deviceSelfName(id),
			label: '', created: 0, namedAt: 0, seen: 0, build: '' };
		// The user's own name for this machine, with the stamp that carries it, so the
		// freshest-namedAt merge still settles it against a rename typed elsewhere.
		if (line.label && ms(line.namedAt) >= ms(me.namedAt)) {
			me.label   = line.label;
			me.namedAt = ms(line.namedAt);
		}
		if (!me.build && line.build) me.build = line.build;
		// A device is created ONCE, so the earlier stamp is the true one.
		if (ms(line.created) && (!ms(me.created) || ms(line.created) < ms(me.created))) me.created = ms(line.created);
		if (ms(line.seen) > ms(me.seen)) me.seen = ms(line.seen);
		delete reg[old];
		recordSuper(old, id);
		tombstoneIn(DEVICE_TOMBS_KEY, old);
	}
	if (nominatedDeviceId() === old) nominateDevice(id);
	try { localStorage.removeItem(DEVICE_ID_KEY_LEGACY); } catch (e) { /* the next collect retries */ }
	return true;
}

/// This device's own line, refreshed. Its `seen` only moves once it is stale
/// enough to be worth moving (see SEEN_REFRESH_MS), and the push-skip masks it
/// out besides (`compareKey` in sync.js), so a collect that changes nothing else
/// changes nothing the wire can see.
export function touchSelfDevice(reg) {
	var id = deviceId(), now = Date.now();
	// Before anything is read off it: a line this device wrote under its old id
	// carries the name, the creation stamp and the build that belong on the new one.
	migrateLegacySelfLine(reg, id, now);
	var me = reg[id];
	var mine = '';
	try { mine = buildId(); } catch (e) { /* the build id is not readable yet */ }
	if (!me) me = reg[id] = { name: deviceSelfName(id), label: '', created: now, namedAt: 0, seen: now, build: mine };
	else if (now - ms(me.seen) >= SEEN_REFRESH_MS) me.seen = now;
	// The running build changed (this device updated): stamp it and bump `seen` so
	// the fresher line WINS the freshest-wins merge and the new build reaches the
	// fleet -- the same way a rename bumps `namedAt`. Only when the build is KNOWN
	// and actually different, so an unread id never blanks a good one and an
	// unchanged build never churns the parcel (which would push ~163K for nothing).
	if (mine && mine !== me.build) { me.build = mine; me.seen = now; }
	// This machine's own mobility answer, on its own line, so a PEER that has only
	// the roster (no beat from this device yet) still seats it correctly. Stamped
	// only when it CHANGES, for the same reason the build is: an unchanged value
	// must not churn the parcel.
	var mob = isMobileDeviceSelf();
	if (typeof me.mobile !== 'boolean' || me.mobile !== mob) { me.mobile = mob; me.seen = now; }
	// This build runs a handed-off turn on its asker's set, so it says so on its own line,
	// the advertisement an asker reads before it hands a turn over (`honoursModelSet`).
	// Stamped once, with `seen`, so the line carrying it wins the merge.
	if (me.modelset !== true) { me.modelset = true; me.seen = now; }
	// A name chosen while pairing, on a device that had no line to put it on
	// until this moment.
	//
	// Only when it CHANGES the name. `pendingDeviceLabel` consumes the parked value with a
	// `removeItem` whose failure is swallowed, so a browser that declines the delete hands
	// the same name back on every collect -- and stamping `namedAt` with the clock each time
	// makes this device's parcel differ from the one it last sent, for ever. `push` then
	// never takes its skip branch, every push wakes the other device, whose merge sees a
	// strictly newer `namedAt` and pushes back. That is an endless loop between two devices
	// that are both behaving correctly, and it can only start on a device that has just
	// redeemed a pairing code -- which is where it was reported from.
	var chosen = pendingDeviceLabel();
	if (chosen && chosen !== me.label) { me.label = chosen; me.namedAt = DaimondStamp.next(me.namedAt); }
	return reg;
}

/// Give a device the name its owner calls it by, or clear it back to what the
/// device says about itself. Returns the roster as written, or null for an id
/// that is not on it.
///
/// Any device on the roster, not only this one. A user standing at their
/// laptop is exactly who wants to say which of these lines is the phone, and
/// the stamp is what carries that back to the phone.
///
/// `derived` seeds a line for a device known only from its presence beat -- one the
/// panel drew from the live beat map before its roster line had synced here (the
/// disjoint-roster case). Without it a rename on such a device found no line and
/// silently did nothing; with it the name has somewhere to live and travels on the
/// next parcel like any other.
export function renameDevice(id, label, derived) {
	if (!DEVICE_ID_RE.test(String(id || ''))) return null;
	var reg = loadDevices(), d = reg[id];
	if (!d) {
		var seed = String(derived || '').slice(0, DEVICE_NAME_MAX);
		if (!seed) return null;			// nothing to seed a line from
		var t0 = Date.now();
		d = reg[id] = { name: seed, label: '', created: t0, namedAt: 0, seen: t0, build: '' };
	}
	var next = String(label == null ? '' : label).trim().slice(0, DEVICE_NAME_MAX);
	if (next === d.label) return reg;			// nothing changed, nothing to push
	d.label   = next;
	d.namedAt = DaimondStamp.next(d.namedAt);	// past the name it replaces, whatever the clocks
	return saveDevices(reg);
}

/// The roster as it goes into the parcel, and as the drawer draws it: this
/// device's line refreshed, the rest exactly as they were merged.
///
/// WHO SENT IT, marked on the one line that can say so. A receiver has to know
/// which device a parcel came from to record that device's chunk refs under
/// its own slot (`notePeerRef`), and nothing else in the parcel says: every
/// section is a merged account fact, and `seen` only moves once it is stale,
/// so "the freshest line" is not the sender. `deviceEntry` is a whitelist, so
/// the mark is dropped by `mergeDevices` and by `saveDevices` -- it exists
/// only in the copy that travels, can never persist in a stored roster, and is
/// deterministic, so the push-skip comparison still holds.
export function collectDevices() {
	var out = saveDevices(touchSelfDevice(loadDevices()));
	var me = deviceId();
	if (out[me]) {
		var mine = {}, k;
		for (k in out[me]) { if (Object.prototype.hasOwnProperty.call(out[me], k)) mine[k] = out[me][k]; }
		mine.self = 1;				// last, so the field order stays fixed.
		out[me] = mine;
	}
	return out;
}

/// Merge a roster that arrived from another device.
///
/// Per line, the freshest `seen` wins, STRICTLY — equal stamps keep what is
/// here, so a device that has not moved is never rewritten and the parcel does
/// not change for nothing. A line neither side has seen simply unions in, and
/// a parcel with no roster at all is a device that predates this: nothing
/// happens, in either direction.
///
/// The user's name for a device is merged SEPARATELY, on its own `namedAt`
/// stamp, and it cannot be otherwise. Each device refreshes only its OWN
/// `seen`, so a name typed on the laptop for the phone sits on a line the
/// laptop never touches again: on the next pull the phone's own fresher line
/// would win and the name would vanish, on the very device it was meant for.
/// With its own stamp the two decisions cross in either direction — the phone
/// keeps saying where it has been, the laptop keeps saying what it is called.
///
/// A removal is honoured here as well as in `loadDevices`, or the union would
/// hand the line straight back on the pull that carried it.
///
/// The same answer whichever side is here (SIM-17): see `mergeDeviceLine`. A
/// merged roster the box refuses THROWS, so the section is re-pulled (A5).
export function mergeDevices(incoming) {
	if (!incoming || typeof incoming !== 'object') return;
	var reg = loadDevices(), live = {};
	var tombs = loadTombMap(DEVICE_TOMBS_KEY);
	Object.keys(incoming).forEach(function (id) {
		if (!incoming[id] || typeof incoming[id] !== 'object') return;
		if (!deviceRemoved(tombs, id, incoming[id].seen)) live[id] = incoming[id];
	});
	var before = rosterRecord(reg), next = mergeRosters(reg, live);
	if (JSON.stringify(next) !== JSON.stringify(before)) DaimondStore.putMerged(DEVICES_KEY, next, mergeRosters);
}

/// Two rosters as one, line by line: the law `mergeDevices` applies and the one
/// an owed roster is retried under.
function mergeRosters(a, b) {
	var out = {};
	[a, b].forEach(function (reg) {
		if (!reg || typeof reg !== 'object') return;
		Object.keys(reg).forEach(function (id) {
			if (!DEVICE_ID_RE.test(id) || !reg[id] || typeof reg[id] !== 'object') return;
			var r = deviceEntry(reg[id]);
			out[id] = out[id] ? mergeDeviceLine(out[id], r) : r;
		});
	});
	return rosterRecord(out);
}

/// One device's line, merged from two copies, the same whichever copy is here.
///
/// The line follows the later `seen`, and an equal `seen` the canonically greater
/// line. A device is created once, so the EARLIEST `created` either copy holds is
/// the true one: a copy that reached us later cannot have been created later. The
/// name follows its own later `namedAt`, and an equal one the smaller label.
function mergeDeviceLine(a, b) {
	// `modelset` in the key, so at an equal `seen` the line that says it wins: an older build
	// writes its peers' lines back without the field (D-20261018-09 OR).
	var key = function (d) { return JSON.stringify([d.name, d.build, typeof d.mobile === 'boolean' ? d.mobile : null,
		d.modelset === true ? true : null]); };
	var line  = (b.seen > a.seen || (b.seen === a.seen && key(b) > key(a))) ? b : a;
	var named = (b.namedAt > a.namedAt || (b.namedAt === a.namedAt && b.label < a.label)) ? b : a;
	var out = deviceEntry(line);
	out.created = (a.created && b.created) ? Math.min(a.created, b.created) : (a.created || b.created);
	out.label   = named.label;
	out.namedAt = named.namedAt;
	return deviceEntry(out);
}

// ── The nominated always-on runner ─────────────────────────
//
// One device the account names as the runner that should pick up a dispatched
// turn, so a laptop someone closes mid-turn does not race in and grab it. It is
// an ACCOUNT scalar -- WHICH single device -- not a per-line fact, so it rides as
// its own freshest-`at`-wins record beside the roster rather than as a flag on
// each line. A boolean per line has no principled winner when two devices name
// different runners (the roster unions, and both would read as nominated); one
// scalar keeps EXACTLY ONE nominee for free and makes "nominate this one" clear
// any other outright. An empty id is un-nominated; a fresher empty record
// propagates the clearing, like handle and look. It only changes WHO attempts a
// claim -- the lease CAS (peer.js) is still the single-runner arbiter.
var NOMINATED_KEY = 'daimond-nominated';	// { id, at }: the account's chosen runner

/// The nomination as it rides the parcel, or null when this device has never held
/// one. Verbatim -- collectSync never stamps -- so a parcel this device already
/// agrees with serialises to the same bytes and the push still skips. A fixed
/// field order, for that same byte-stability.
export function nominationSnapshot() {
	var rec = DaimondStore.get(NOMINATED_KEY, null);
	if (!rec || typeof rec !== 'object') return null;
	var id = String(rec.id || '');
	if (id && !DEVICE_ID_RE.test(id)) return null;
	return { id: id, at: ms(rec.at) };
}

/// The nominated device's id, or '' when none is set.
export function nominatedDeviceId() {
	var rec = nominationSnapshot();
	return rec ? rec.id : '';
}

/// Name ONE device the always-on runner, or clear the nomination with ''. Exactly
/// one per account: this is a single scalar, so naming a device replaces any prior
/// nominee outright. Stamped past the nomination it replaces, whatever the clocks
/// (`DaimondStamp.next`, A1), which is how the choice wins over an older one on
/// every device (adoptNomination).
export function nominateDevice(id) {
	var next = String(id || '');
	if (next && !DEVICE_ID_RE.test(next)) return null;
	var prev = DaimondStore.get(NOMINATED_KEY, null);
	var rec = { id: next, at: DaimondStamp.next(prev && typeof prev === 'object' ? prev.at : 0) };
	// A box too full to store it holds the choice owed in this tab, where it
	// stands, travels and is retried (SIM-10b).
	DaimondStore.put(NOMINATED_KEY, rec, fresherNomination);
	// Naming (or clearing) the runner changes where the next turn goes, so the line
	// under the composer says so at once rather than at the next beat.
	try { renderSeatSwitch(); } catch (e) { /* the next presence beat redraws it */ }
	return rec;
}

/// Merge a nomination that arrived from another device: the fresher `at` wins,
/// and is written VERBATIM -- no restamp -- so a record this device already holds
/// moves nothing and the next parcel is unchanged. An equal stamp is broken the
/// same way on every device (the smaller id, A3), and the same record on both
/// sides is no win, which is what stops two devices pushing at each other over a
/// nomination they already agree on.
///
/// A merged nomination the box refuses THROWS, so the roster section is reported
/// failed and re-pulled rather than read as applied (SIM-16, A5).
export function adoptNomination(rec) {
	if (!rec || typeof rec !== 'object') return;
	var id = String(rec.id || '');
	if (id && !DEVICE_ID_RE.test(id)) return;
	var mine = DaimondStore.get(NOMINATED_KEY, null), next = { id: id, at: ms(rec.at) };
	if (fresherNomination(mine, next) === next) DaimondStore.putMerged(NOMINATED_KEY, next, fresherNomination);
}

/// The fresher of two nominations, `b` only when it beats `a`: the law the merge
/// applies and the one an owed nomination is retried under.
function fresherNomination(a, b) {
	if (!b || typeof b !== 'object') return a;
	if (!a || typeof a !== 'object') return b;
	return DaimondStamp.beats(b.at, b, a.at, a, nominationRank) ? b : a;
}

/// A nomination's tie rank: the SMALLER id ranks higher, so a tie goes the same
/// way on every device and a clearing ('') wins it. Each code unit complemented,
/// and a top unit closing it so a prefix outranks what it prefixes.
function nominationRank(r) {
	var id = String((r && r.id) || ''), out = '';
	for (var i = 0; i < id.length; i++) out += String.fromCharCode(0xffff - id.charCodeAt(i));
	return out + '\uffff';
}

// ── Reconciling the roster against who is actually here ────
//
// The roster is an add-only UNION (mergeDevices): a line a device stops writing is
// left behind for ever, because nothing beats a dead id back to life and nothing
// prunes it. A superseded line -- one whose machine is here now under a different
// id -- is a GHOST, and the list filled with them while this file and identity.js
// minted ids in two separate spaces.
//
// A GHOST IS A RECORDED FACT, NEVER AN INFERENCE FROM A NAME. It was the latter
// until 2026-09-12: a stale line was called a ghost when a live device under
// another id carried the same name. Two of a user's machines DO share a name --
// `deviceName()` reads the browser and the platform and nothing else, so two Linux
// Chromes derive "Google Chrome on Linux" identically -- so that test tombstoned
// live peers, and `touchSelfDevice` then re-minted their lines with an empty label,
// losing the user's own name for the machine on every round. What remains is the
// evidence: a tombstone, or a supersession record written by the one-shot migration
// (`migrateLegacySelfLine`). Nothing is guessed.
//
// These read the roster against the LIVE presence set (the gateway beat map) and
// name what is dead. `rosterLiveness` is pure given its arguments, so the
// classification is testable without a browser. Neither touches the lease: the
// money-safety is unchanged, this only marks lines for the Devices UI and moves
// WHICH id the election seats.

/// A presence record's last-seen as a plain ms number (bignum-safe, matching
/// peer.js's leaseMs -- a gateway-ingested stamp can arrive as a bignum).
export function presenceSeenMs(rec) {
	var v = rec && rec.lastSeen;
	return (v && typeof v.toNumber === 'function') ? v.toNumber() : (Number(v) || 0);
}

/// Classify every device the account knows against who is BEATING now.
///
/// `reg` is the merged roster (id -> line), `presence` the live beat map
/// (id -> { name, lastSeen }), `nominee` the nominated id or '', `now` the moment,
/// `windowMs` the freshness bound and `supers` the supersession records
/// (old id -> new id) -- the stored ones when that argument is left out, which is
/// the only thing here that reads storage. Answers
///   { live:{id:true}, stale:{id:true}, ghost:{id:true},
///     nomineeDead:bool, nomineeReplacement:id|'' }
///
/// A device is LIVE when it is beating within the window, STALE when it is known to
/// the account but not beating, and a GHOST only when a supersession record names
/// the line superseded. NOT when a live device happens to share its name: two of a
/// user's machines legitimately derive the same name, and inferring a ghost from
/// that tombstoned live peers and cost them their labels. A merely-asleep machine
/// is STALE, which is all the panel needs to say of it.
///
/// The nominee is DEAD when it is set and not live. Its replacement is whatever the
/// supersession record names, and only while that successor is itself live -- so a
/// stranded star follows the machine it was put on and never lands on a guess.
export function rosterLiveness(reg, presence, nominee, now, windowMs, supers) {
	var r = reg || {}, p = presence || {};
	var n = now == null ? Date.now() : now;
	var w = windowMs || (window.DaimondPeer && DaimondPeer.DISPATCH_FRESH_MS) || 90000;
	var nom = String(nominee || '');
	var sup = supers || loadSupers();
	var live = {};
	Object.keys(p).forEach(function (id) {
		if ((n - presenceSeenMs(p[id])) > w) return;		// not beating within the window
		live[id] = true;
	});
	// Every id worth a verdict: the roster, plus any live device not yet in it.
	var ids = {};
	Object.keys(r).forEach(function (id) { ids[id] = true; });
	Object.keys(live).forEach(function (id) { ids[id] = true; });
	var stale = {}, ghost = {};
	Object.keys(ids).forEach(function (id) {
		if (live[id]) return;						// beating: neither stale nor a ghost
		stale[id] = true;
		if (sup[id]) ghost[id] = true;				// recorded as superseded, not guessed
	});
	var nomineeDead = false, nomineeReplacement = '';
	if (nom && !live[nom]) {
		nomineeDead = true;
		var to = sup[nom] ? String(sup[nom]) : '';
		if (to && to !== nom && live[to]) nomineeReplacement = to;
	}
	return { live: live, stale: stale, ghost: ghost,
		nomineeDead: nomineeDead, nomineeReplacement: nomineeReplacement };
}

/// Move the nomination onto the live device a RECORD says replaced a dead nominee.
///
/// The record is the one-shot id migration's own (`migrateLegacySelfLine`), so the
/// star follows the machine across the id unification on any device that reads the
/// roster, not only the one that migrated. Idempotent: once the nominee beats again
/// there is nothing to move. It will not move the star on a GUESS -- a dead nominee
/// with no supersession record is simply dead, and the election's own fallback
/// (`handoffTarget`) seats a live desktop rather than a device chosen by name.
/// Money-safe: the lease CAS is still the sole single-runner arbiter; this only
/// changes WHICH id the election seats, and it propagates by the ordinary
/// freshest-`at`-wins nomination merge. Answers the id moved to, or ''.
export function reconcileNominee(now, windowMs) {
	try {
		var nominee = nominatedDeviceId();
		if (!nominee) return '';
		var presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
		var live = rosterLiveness(loadDevices(), presence, nominee, now, windowMs);
		if (!live.nomineeDead || !live.nomineeReplacement) return '';
		nominateDevice(live.nomineeReplacement);
		// The old id is now PROVEN superseded: it is the account's own nominee, it is
		// dead, and exactly one live device carries its name. Tombstone it so the add-
		// only union cannot hand the dead star-target back on the next pull. The star
		// has already moved to the live successor, so `removeDevice` does not clear the
		// (now live) nomination -- it only drops the stale line.
		try { removeDevice(nominee); } catch (e) { /* the reseat is the load-bearing half */ }
		return live.nomineeReplacement;
	} catch (e) { return ''; }
}

/// Sweep SUPERSEDED ghost lines from the roster, convergently.
///
/// A ghost is a line a supersession RECORD says was superseded (`rosterLiveness`).
/// `removeDevice` TOMBSTONES it, so the add-only union that would otherwise hand the
/// dead line straight back on the next pull cannot (`deviceRemoved`,
/// `mergeDevices`): the tombstone rides `deviceTombs` in the parcel, so every device
/// converges on the same pruned roster. That is why a local delete is not enough --
/// without the tombstone a peer re-offers the ghost.
///
/// "Asleep is not a ghost" now needs no reasoning at all: an asleep machine has no
/// record against it, so it is STALE and is preserved. The test that DID need the
/// reasoning -- a live device sharing the name -- swept live peers, because two Linux
/// Chromes derive the same name. Never removes self. Answers the ids removed.
export function pruneGhosts(now, windowMs) {
	var out = [];
	try {
		var n = now == null ? Date.now() : now;
		var presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
		var reg  = loadDevices();
		var live = rosterLiveness(reg, presence, nominatedDeviceId(), n, windowMs);
		var self = deviceId();
		Object.keys(live.ghost).forEach(function (id) {
			if (id === self) return;						// never this device
			if (!reg[id]) return;
			removeDevice(id);
			out.push(id);
		});
	} catch (e) { /* best-effort: a stranded ghost is cosmetic, never a hazard */ }
	return out;
}

/// Reseat a stranded star onto its live successor, then sweep superseded ghosts.
///
/// The single call the app makes wherever the roster meets presence -- the sync
/// merge, the Devices panel, and (the load-bearing addition) the dispatch election --
/// so a re-minted fleet converges on a live nominee and a clean roster without any
/// caller reasoning about it. Money-safe: neither step touches the lease or the
/// consent CAS; both only change WHICH id the election seats and which dead lines
/// linger. Answers `{ moved, pruned }` for the tests.
export function reconcileRoster(now, windowMs) {
	// NOTHING IS DECIDED AGAINST AN EMPTY PRESENCE MAP. Both halves read the roster
	// AGAINST who is beating, so with no beats yet every line reads stale: a superseded
	// line is then a ghost, `removeDevice` tombstones it, and -- if it is the account's
	// nominee -- the star is CLEARED and the empty record propagates on its own fresher
	// `at`, un-starring the fleet from a device that had simply not beaten yet. The
	// sync merge calls this on a pull, which on a cold boot runs before the first
	// presence beat, so that window is real. A later round reconciles with evidence.
	var presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
	if (!Object.keys(presence).length) return { moved: '', pruned: [] };
	var moved  = reconcileNominee(now, windowMs);
	var pruned = pruneGhosts(now, windowMs);
	return { moved: moved, pruned: pruned };
}

// ── Workspace files (the other half of "the work") ─────────
// Chats have a natural merge (union transcripts); files do not, so they use
// a 3-way compare against a stored per-file hash BASELINE — the state as of
// the last successful sync. That lets a pull tell "the other device changed
// this" from "I changed this" without any modification time (file_list gives
// none), and it NEVER clobbers: a file changed on both sides differently is
// preserved as a `.synced` sidecar rather than overwritten. Only the OPFS
// sandbox is synced — a real folder is the user's own disk, device-specific.
export var SYNC_FILE_MAX        = 128 * 1024;		// carry inline in the blob up to here.
var SYNC_FILES_TOTAL_MAX = 8 * 1024 * 1024;	// the standalone inline-files budget; a
						// parcel uses `syncFilesBudget` instead (the
						// parcel less the Diamond reference floor).
// The ceiling on one offloaded file. The pipeline streams now -- a slice is
// read, sealed, sent and dropped -- so this is no longer a memory limit but a
// manifest one: every chunk becomes an entry inside the sync blob, and the
// blob has its own ceiling. The chunk size grows with the file to keep that
// entry count in hand (chunks.js chunkSizeFor).
var SYNC_CHUNK_FILE_MAX  = 1024 * 1024 * 1024;
var SYNC_CHUNK_TOTAL_MAX = 4 * 1024 * 1024 * 1024;	// budget for all offloaded bytes.
// What the WHOLE parcel has to stay under, and THE NUMBER THAT DECIDES IT IS
// STEEL'S. Three ceilings sit on this path and only the smallest one is real:
//
//   32 MiB  `max_bytes` on /api/sync (gateway/src/settings.rs). Nothing reaches it.
//   16 MiB  the gateway's own body cap (gateway/src/app_main.rs, MAX_BODY_BYTES).
//    8 MiB  Steel's `http_max_body_bytes`, TLS terminated in FRONT of the gateway,
//           its default standing (fe2o3_steel/src/srv/cfg.rs). The front door.
