/// parcel is a Diamond that has not travelled YET, not one the other device is
/// entitled to delete. `diamondsComplete` says so in the parcel, and the caller
/// tells the user which ones stayed behind -- a census that quietly drops content
/// is the defect `dev/verify_dataloss.mjs` exists about.
///
/// Freshest first, so what the user is working on is what travels when not all of
/// it does; ties broken by id, because the parcel is compared byte-for-byte
/// against the last one pushed and an order that depended on how the store
/// enumerated would push for ever.
///
/// # Arguments
/// * `budget` - The most exported bytes the Diamonds may take of this parcel.
export async function collectDiamonds(budget, plan) {
	trail('sync collect', 'budget ' + Math.round(budget / 1024) + ' kB');
	var out = { list: [], left: [], complete: true, bytes: 0 };
	// The store is walked, sorted and sized ONCE per parcel by `planDiamonds`, and
	// the plan is handed in — so the reference room reserved out of the parcel BEFORE
	// the files spent against it (see `collectSync`) is measured from the very same
	// figures the collection spends here. A caller that passes no plan gets one
	// computed now, which keeps `collectDiamonds` usable on its own.
	if (!plan) plan = await planDiamonds();
	if (!plan.ok) { out.complete = false; return out; }   // no store to read: send nothing, delete nothing
	var held       = plan.held;         // live Diamonds, freshest first, trashed last
	var models     = plan.models;
	var sizes      = plan.sizes;        // parallel to held; null where the engine cannot size one
	var canOffload = plan.canOffload;   // may a Diamond leave as an `@d/` reference this round?
	var refReserve = plan.refReserve;   // bytes held back for the references, 0 when offload is down
	var liveIds = {};
	var used = 0;
	// What each entry's copy descends from (`anc`, see `diamondAncOf`), from the record
	// read once. A copy this device made is recorded the first time a parcel carries
	// it: its lineage, and its tags, links, name and grants, so a later two-sided
	// merge can find the copy both sides last shared. The lineage moves only with the
	// entry's stamp, so it never pushes alone and the fixed point holds.
	var recv = readDiamondRecv(), seen = readDiamondSeen(), recvCh = {}, seenAdd = {};
	var lineage = function (id, stamp, data) { return entryLineage(recv, seen, id, stamp, data, recvCh, seenAdd); };
	// A Diamond the parcel could not carry falls into two very different cases,
	// and telling them apart is the whole of the fix here. GENUINE: it is small
	// enough to ride inline anyway (offload would not have helped) and the parcel
	// simply has no room -- the account has more Diamonds than one parcel holds,
	// and naming it is the only way the user can act. TRANSIENT: it is large
	// enough to need offload, but offload was not available THIS ROUND (the chunk
	// store not yet ready just after a reload, or an identity that re-locked
	// mid-collect) or an upload the gateway refused -- which `DaimondChunks
	// .standRefused` already says, in its own words and persistently. A transient
	// strand is HELD, not named: the next push, once the store is ready, carries
	// it. Telling the user to "make it smaller" for a Diamond that is neither too
	// big nor staying behind -- and telling them in a toast gone in four seconds
	// -- was a false alarm. A held Diamond is absent from `out.list` exactly as a
	// left one is, so the parcel and its fixed point are unchanged either way.
	function strand(id, name, genuine) {
		out.complete = false;
		if (genuine) out.left.push({ id: id, name: name || id });
		else out.held++;
	}
	out.held = 0;
	// Did offload turn out to be unavailable THIS ROUND? True from the start when
	// canOffload is false (store not ready, identity re-locked), and set below when
	// an upload the gateway refused makes a large Diamond fall back to riding inline.
	// It matters at the end: a large Diamond riding inline spends budget the small
	// ones behind it needed, so their strand is transient, not genuine. seq 212 held
	// the large Diamond itself but still NAMED the small ones caught in its wake --
	// this is the other half of that fix.
	var offloadStalled = !canOffload;
	// IS THERE ROOM FOR THE REFERENCES AT ALL? The reserve was held back from the
	// parcel before the files spent against it, so an ordinary round hands this
	// collector at least `refReserve` and every Diamond's few hundred bytes fit. A
	// round that hands it LESS is a round where the files overflowed their budget
	// regardless -- the owner's phone was handed exactly zero -- and the Diamonds
	// then took the offload arm, reused their manifests, and were NAMED because even
	// a reference would not fit in nothing. That is a transient strand, not a
	// genuine one: the files shed their overflow next round and the room returns.
	// So it is HELD, like a stalled one, and the banner says nothing.
	var crowded = canOffload && budget < refReserve;

	// EVERY DIAMOND TRAVELS WHEN OFFLOAD WORKS. Small Diamonds used to ride inline
	// for an old receiver's sake and were NAMED "did not fit" when the inline budget
	// -- already eaten by the workspace files ahead of them -- had no room. The owner
	// runs latest on every device, so a small Diamond may leave as an `@d/` reference
	// like a large one: a few hundred bytes that fit in any budget. So the inline blob
	// is now only the CHEAP path for the freshest few; the rest offload. This mirrors
	// `collectChatsRefs` -- pick the inline set first, offload the remainder. The
	// sizes and the reference reserve were measured once in `planDiamonds`, ahead of
	// the files, so the reserve is already subtracted from what the files could take.
	//
	// What inline may spend: the budget less the reserved reference room. When the
	// references alone would fill the budget (a pathological store), inline gets
	// nothing and every Diamond offloads.
	var inlineCap = canOffload ? Math.max(0, budget - refReserve) : budget;
	// Which Diamonds ride inline: the freshest small ones, in the store's existing
	// order (freshest first, trashed last), while the inline cap has room. A Diamond
	// over SYNC_FILE_MAX is never inline -- it offloads as it always did. The set is a
	// deterministic function of the sizes, so two collects of an unchanged store pick
	// the same set and the parcel stays the byte-stable fixed point the push-skip
	// needs. Empty when nothing can be offloaded: then the `!canOffload` path below
	// carries every Diamond inline and holds any that overflow, retried next round.
	//
	// A Diamond that already leaves as a reference stays one while its `touched`
	// stands (the shape law, `diamondRefStands`): a Diamond is a candidate for the
	// inline set only while no manifest stands at its stamp.
	var inline = canOffload ? diamondInlineSet(held, sizes, inlineCap, function (d) {
		return diamondRefStands(diamondManifest(d.id), diamondStamp(d));
	}) : {};

	for (var i = 0; i < held.length; i++) {
		var d = held[i], data;
		liveIds[d.id] = 1;
		var size = sizes[i];
		var stamp = diamondStamp(d);
		var ckey = '@d/' + d.id;
		var stored = canOffload ? DaimondCloud.contentGet(ckey) : null;

		// RIDES INLINE: chosen for the inline set, or nowhere to offload it to. The
		// cheap path -- the bytes travel in the blob and no chunk is uploaded. If it
		// held a manifest from a round when it offloaded, that manifest is now
		// unreferenced and goes, so its chunks are swept.
		if (!canOffload || inline[d.id]) {
			if (stored && DaimondCloud.contentForget) DaimondCloud.contentForget(ckey);
			if (size !== null && used + size > budget) {
				// Only reachable with canOffload false -- an inline Diamond is chosen
				// against the cap, so it fits. Held, not named: once offload is back it
				// leaves as a reference and the room returns. seq-215 stall behaviour.
				strand(d.id, d.name, false);
				continue;                    // never exported, so never held twice
			}
			try { data = await diamondApp().export_diamond(d.id); }
			catch (e) { out.complete = false; continue; }  // one unreadable Diamond must not hold up the rest
			stamp = packHeadStamp(data) || stamp;	// what the bytes carry (B1)
			// `continue`, not `break`: one Diamond must not stop the fresh ones behind it.
			// Weighed as the door weighs it, JSON-escaped UTF-8 (see `SYNC_DOOR_RESERVE`).
			var dataBytes = jsonBytes(JSON.stringify(data));
			if (used + dataBytes + DIAMOND_ANC_BYTES > budget) {
				strand(d.id, d.name, false);
				data = null;                 // let it go before the next one is read
				continue;
			}
			var anc = lineage(d.id, stamp, data);
			used += dataBytes + JSON.stringify(anc).length;
			out.list.push({
				id:      d.id,
				updated: d.updated || 0,
				// A device that predates the second stamp sends none, and the
				// receiver falls back to `updated` — which is what `touched`
				// means on such a device anyway.
				touched: stamp,
				anc:     anc,
				model:   models[d.id] || null,
				data:    data,
			});
			continue;
		}

		// OFFLOADED. The heavy export moves to chunks and only a reference
		// rides in the parcel. Reuse the stored manifest when the Diamond has
		// not been touched since it was made -- no export, no re-offload, and
		// the index bytes do not move, which is the fixed point the parcel
		// depends on. `touched` moves on every change (tags and links
		// included), and an import lays stamps down wholesale, so it is a safe
		// change-key here.
		var ref = null, lineageData = null;
		if (diamondRefStands(stored, stamp)) {
			ref = { v: stored.v, size: stored.size, key: stored.key, chunks: stored.chunks };
		} else {
			var text;
			try { text = await diamondApp().export_diamond(d.id); }
			catch (e) { out.complete = false; continue; }
			// The manifest and the entry are stamped with what the bytes carry (B1),
			// so the reuse check above compares like with like on the next collect.
			stamp = packHeadStamp(text) || stamp;
			var mani = null;
			try { mani = await DaimondChunks.offloadBytes('d:' + d.id, new TextEncoder().encode(text)); }
			catch (e) { mani = null; }        // gateway unreachable, store full: fall back to inline
			// A manifest is only usable if it was BOTH offloaded AND durably
			// recorded in the index. A record lost to quota (`contentSet` false)
			// leaves the parcel naming a `dataRef` whose chunks the next commit --
			// built from the index that never took them -- does not declare, so the
			// gateway sweeps them and the far device gets a metadata-only Diamond.
			// On either failure the Diamond rides inline this round exactly as it
			// did before offload existed, and the collector retries next round.
			var recorded = mani ? DaimondCloud.contentSet(ckey, {
				v: mani.v, size: mani.size, key: mani.key, chunks: mani.chunks, touched: stamp }) : false;
			if (!recorded) {
				offloadStalled = true;   // a payload that should have left is riding inline
				// An offload that SUCCEEDED but could not be recorded is a full
				// localStorage, not a full store: say so, once, as a standing signal.
				if (mani) noteCloudIndexStuck();
				// The offload could not be recorded this round, so the Diamond rides
				// inline instead of not travelling at all -- exactly as it did
				// before offload existed, budget permitting.
				var textBytes = jsonBytes(JSON.stringify(text));
				if (used + textBytes + DIAMOND_ANC_BYTES > budget) {
					// The offload was ATTEMPTED and failed (store full, the network,
					// or an index that would not write): held, never named "too big".
					// A store-full refusal has already been said honestly and
					// persistently by DaimondChunks.standRefused; an index that would
					// not write raised storageAlarm above, so a second, misleading
					// toast here would only muddy it.
					strand(d.id, d.name, false);
					text = null; continue;
				}
				var ancI = lineage(d.id, stamp, text);
				used += textBytes + JSON.stringify(ancI).length;
				out.list.push({
					id:      d.id,
					updated: d.updated || 0,
					touched: stamp,
					anc:     ancI,
					model:   models[d.id] || null,
					data:    text,
				});
				text = null;
				continue;
			}
			lineageData = text;              // the bytes that left, read for the record below
			text = null;                     // freed before the next Diamond is read
			ref = { v: mani.v, size: mani.size, key: mani.key, chunks: mani.chunks };
		}
		// The reference is a few hundred bytes and room for it was reserved out of the
		// budget above, so it fits in all but a pathological store. The real ceiling on
		// offloaded content is the chunk store's, which the commit counts it against
		// alongside the files.
		var refBytes = JSON.stringify(ref).length + DIAMOND_ANC_BYTES;
		if (used + refBytes > budget) {
			// The content is offloaded and only a few hundred bytes of reference would
			// travel, yet even that does not fit: the parcel is genuinely full -- many
			// Diamonds' references plus the files ahead of them exceed one parcel. The
			// reserve is sized to keep this effectively unreachable for an ordinary
			// store, and it is the one case a Diamond is honestly named.
			strand(d.id, d.name, true);
			continue;
		}
		var ancR = lineage(d.id, stamp, lineageData);
		lineageData = null;
		used += refBytes - DIAMOND_ANC_BYTES + JSON.stringify(ancR).length;
		out.list.push({
			id:      d.id,
			updated: d.updated || 0,
			touched: stamp,
			anc:     ancR,
			model:   models[d.id] || null,
			dataRef: ref,
		});
	}
	recordDiamondCopies(recvCh, recv, seenAdd, null);
	// A Diamond that is gone leaves its manifest naming chunks nothing refers
	// to; drop those so the next commit sweeps them. Writes only on a real
	// deletion, so a no-op collect leaves the index byte-identical.
	if (window.DaimondCloud && DaimondCloud.contentReap) DaimondCloud.contentReap('@d/', liveIds);
	// On a stalled round nothing is NAMED. A small Diamond overflowed only because a
	// large one that should have offloaded spent its budget inline; once offload
	// works the large payload leaves the parcel and the room comes back, so telling
	// the user their Diamond will not travel "until there is room" is a false alarm
	// on a picture that is about to change. Every strand becomes a HOLD, retried next
	// sync, exactly as a large one already is -- and the honest notice the user does
	// see is the chunk store's own `standRefused`, which names the real remedy.
	if (crowded) {
		diag('parcel diamonds crowded', Math.round(budget / 1024) + 'kB for '
			+ Math.round(refReserve / 1024) + 'kB of references: nothing named, '
			+ out.left.length + ' held for next round');
	}
	if ((offloadStalled || crowded) && out.left.length) {
		out.held += out.left.length;
		out.left = [];
	}
	out.bytes = used;
	trail('sync collected', out.list.length + ' of ' + held.length
		+ ', ' + Math.round(used / 1024) + ' kB, ' + out.left.length + ' left behind, '
		+ out.held + ' held for offload');
	return out;
}

export function install() { // page-split: install
	// page-split: install 20

	// THE WALK ITSELF, memoised. A pull applies, then commits its own baseline, both
	// against the census the parcel was already built from -- three callers a round,
	// each walking the whole tree to answer the same question. Keyed on the SORTED
	// FLAGGED roots, so flagging a folder or taking the flag off misses the cache
	// rather than answering for a share that no longer matches -- and
	// `toggleAttachShare` clears it outright, at the moment the set moved rather than
	// a round later; good for `SYNC_WALKPLAN_TTL_MS`,
	// long enough to cover one round's three callers and short enough that a folder
	// the user just grew past the ceiling is re-measured well inside the next one.
	// `daimond-file-written` clears it outright, for a write THIS DEVICE makes
	// mid-round -- an edit that arrives some other way (Syncthing, git, the user's
	// own editor) waits out the TTL like everything else past the ceiling does.
	/* var */ pg._walkPlanCache     = null;			// { key, at, plan }
	// page-split: install 21

	// A WRITE THIS DEVICE MAKES MID-ROUND invalidates the memoised walk outright: the
	// census `commitFileBaseline` is about to run must see it, not the plan from up to
	// `SYNC_WALKPLAN_TTL_MS` ago.
	window.addEventListener('daimond-file-written', function () { pg._walkPlanCache = null; });
	// page-split: install 22
	// Whether THIS round's presence question was answered at all. An unanswered query
	// is not evidence of absence (see `verifyManifestPresence`), so it is not evidence
	// of presence either, and a manifest reused under one must not confirm anything.
	/* var */ pg._presenceAnswered = false;
	// page-split: install 23

	// Whether the last `applySync` merged the parcel's chunk index WHOLE: in the sandbox, or
	// in a folder where no entry of it fell outside the share. Read by `syncIndexAt` when the
	// version that apply was of is adopted.
	/* var */ pg._chunkedWhole = false;
	// page-split: install 24

	// The conflict copies the last merge wrote, for the panel and for the verifier.
	/* var */ _lastConflicts = [];
	// page-split: install 25

	/// The room the last `collectSync` measured for the three inline sections (see
	/// `SYNC_DOOR_RESERVE`), so the baseline commit and the pull merge hand `collectFiles`
	/// the same budget the parcel did -- the agreement `inlineSoftCap` names as
	/// load-bearing. Null until the first collect of the sitting.
	/* var */ pg.syncRoomLast = null;
} // page-split: end install
